function states.parse_eompls_rest(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 7 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_eompls_rest = tree:add(f_hdr_eompls_rest, buf(math.floor(off / 8)))
  if off + 12 > avail then
    hdr_eompls_rest:add_proto_expert_info(ef_error, "out of bounds in eompls_rest.reserved")
    return off
  end
  hdr_eompls_rest:add(f_eompls_rest_reserved, buf(math.floor(off / 8), math.floor((off % 8 + 12 + 7) / 8)), buf():bitfield(off, 12))
  off = off + 12
  if off + 16 > avail then
    hdr_eompls_rest:add_proto_expert_info(ef_error, "out of bounds in eompls_rest.seq_no")
    return off
  end
  hdr_eompls_rest:add(f_eompls_rest_seq_no, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), buf():bitfield(off, 16))
  off = off + 16
  return states.parse_ethernet2(buf, pinfo, tree, off, depth)
end

function states.parse_ethernet2(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 7 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_ethernet2 = tree:add(f_hdr_ethernet2, buf(math.floor(off / 8)))
  if off + 48 > avail then
    hdr_ethernet2:add_proto_expert_info(ef_error, "out of bounds in ethernet2.dst_addr")
    return off
  end
  hdr_ethernet2:add(f_ethernet2_dst_addr, buf(math.floor(off / 8), 6))
  off = off + 48
  if off + 48 > avail then
    hdr_ethernet2:add_proto_expert_info(ef_error, "out of bounds in ethernet2.src_addr")
    return off
  end
  hdr_ethernet2:add(f_ethernet2_src_addr, buf(math.floor(off / 8), 6))
  off = off + 48
  if off + 16 > avail then
    hdr_ethernet2:add_proto_expert_info(ef_error, "out of bounds in ethernet2.ether_type")
    return off
  end
  hdr_ethernet2:add(f_ethernet2_ether_type, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), buf():bitfield(off, 16))
  off = off + 16
  add_payload(buf, tree, off)
  return off
end

function p.dissector(buf, pinfo, tree)
  local root = tree:add(p, buf())
  states.parse_ethernet(buf, pinfo, root, 0, 0)
end

-- Postdissector: runs on every frame after built-in dissection,
-- so our tree appears alongside Wireshark's own — side-by-side
-- comparison for free, no dissector-table precedence fights.
register_postdissector(p)
